using UnityEngine;
using Partition = BridgeBuilder.Bridges.MovableRoadGeometry.Partition;

namespace BridgeBuilder.Bridges;

// Both decks share these measured seams and bone 3 (connection 100).
// Bones 1/2 are counterweights; road and paint must never bind to them.
// Generated by Lift03RoadTops.py from both detailed native Geometry levels.
internal static class Lift03RoadPartitions
{
    internal const float MovingEnd = 79.966796875f;
    internal const float FixedStart = 79.998046875f;
    internal const float FixedEnd = 127.96484375f;

    internal static readonly Partition Carriageway = Cut(-FixedEnd, Partition.Gap,
        Cut(-FixedStart, new Partition(0),
            Cut(-MovingEnd, Partition.Gap,
                Cut(MovingEnd, new Partition(3),
                    Cut(FixedStart, Partition.Gap,
                        Cut(FixedEnd, new Partition(0), Partition.Gap))))));

    private static Partition Cut(float station, Partition negative, Partition positive)
    {
        var frame = Matrix4x4.identity;
        frame.m23 = -station;
        return new Partition(frame, negative, positive);
    }
}
